action.code:
if (!root) return false;
Node* cur = root;
while (!cur->is_leaf) {
    int l = 0, r = static_cast<int>(cur->keys.size()) - 1;
    int idx = 0;
    while (l <= r) {
        int mid = l + (r - l) / 2;
        if (cur->keys[mid] < key) {
            idx = mid + 1;
            l = mid + 1;
        } else {
            r = mid - 1;
        }
    }
    cur = cur->children[idx];
}
int l = 0, r = static_cast<int>(cur->keys.size()) - 1;
while (l <= r) {
    int mid = l + (r - l) / 2;
    if (cur->keys[mid] == key) return true;
    if (cur->keys[mid] < key) l = mid + 1;
    else r = mid - 1;
}
return false;
// END_CODE

